import React, { useState, useRef, useCallback, useEffect } from 'react';
import Webcam from 'react-webcam';
import { attendanceAPI } from './api_service';

const CameraRecognition = () => {
  const COLORS = {
    primary: '#4F46E5',
    success: '#10B981',
    danger: '#EF4444',
    warning: '#F59E0B',
    textMain: '#1E293B',
    textMuted: '#64748B',
    border: '#E2E8F0',
    surface: '#FFFFFF'
  };

  const webcamRef = useRef(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const [autoMode, setAutoMode] = useState(false);

  const videoConstraints = {
    width: 1280,
    height: 720,
    facingMode: "user"
  };

  const handleCapture = useCallback(async () => {
    if (!webcamRef.current) return;

    setLoading(true);
    setError(null);
    setResult(null);   // reset précédent résultat

    try {
      const imageSrc = webcamRef.current.getScreenshot();
      if (!imageSrc) throw new Error("Impossible de capturer l'image");

      const response = await attendanceAPI.recognize(imageSrc);
      const data = response?.data || response || {};

      console.log("✅ API RAW RESPONSE:", response);
      console.log("📊 DATA extraite:", data);

      // Conversion très stricte en primitives (string / number)
      setResult({
        name: String(data.student_name || data.student || data.name || "Inconnu").trim(),
        studentId: String(data.student_id || data.id || "N/A"),
        attendanceId: String(data.attendance_id || "N/A"),
        confidence: (Number(data.confidence || 0) * 100).toFixed(1),
        timestamp: String(data.timestamp || new Date().toLocaleTimeString())
      });

    } catch (err) {
      const errorMsg = err.response?.data?.error 
                    || err.response?.data?.message 
                    || err.message 
                    || "Erreur inconnue lors de la reconnaissance";

      console.error("❌ Erreur reconnaissance:", err);
      setError(String(errorMsg));
      setResult(null);
    } finally {
      setLoading(false);
    }
  }, []);

  // Mode auto
  useEffect(() => {
    let interval = null;
    if (autoMode && !loading) {
      interval = setInterval(handleCapture, 5000);
    }
    return () => {
      if (interval) clearInterval(interval);
    };
  }, [autoMode, loading, handleCapture]);

  const styles = {
    container: { padding: '20px', maxWidth: '600px', margin: '0 auto' },
    card: { backgroundColor: COLORS.surface, borderRadius: '16px', padding: '25px', boxShadow: '0 4px 20px rgba(0,0,0,0.08)', border: `1px solid ${COLORS.border}` },
    title: { margin: '0 0 20px 0', fontSize: '1.4rem', fontWeight: 800, color: COLORS.textMain, textAlign: 'center' },
    cameraWrapper: { position: 'relative', borderRadius: '12px', overflow: 'hidden', backgroundColor: '#000', lineHeight: 0 },
    webcam: { width: '100%', height: 'auto' },
    loaderOverlay: { position: 'absolute', inset: 0, backgroundColor: 'rgba(0,0,0,0.6)', color: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 'bold', fontSize: '16px' },
    buttonGroup: { display: 'flex', gap: '10px', marginTop: '20px' },
    btn: { flex: 1, padding: '12px', border: 'none', borderRadius: '10px', color: '#fff', fontWeight: 'bold', cursor: 'pointer', transition: 'opacity 0.2s', fontSize: '14px' },
    resultArea: { marginTop: '20px', minHeight: '120px' },
    successBox: { padding: '15px', backgroundColor: '#DCFCE7', color: '#166534', borderRadius: '10px', border: '1px solid #BBF7D0' },
    successBoxName: { fontSize: '1.2rem', fontWeight: 'bold', marginBottom: '8px' },
    successBoxRow: { fontSize: '0.9rem', marginBottom: '6px', display: 'flex', justifyContent: 'space-between' },
    successBoxMeta: { fontSize: '0.8rem', color: COLORS.textMuted, marginTop: '8px' },
    errorBox: { padding: '15px', backgroundColor: '#FEE2E2', color: '#991B1B', borderRadius: '10px', border: '1px solid #FECACA' }
  };

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        <h2 style={styles.title}>📷 Reconnaissance Faciale</h2>

        {/* Caméra */}
        <div style={styles.cameraWrapper}>
          <Webcam
            ref={webcamRef}
            audio={false}
            screenshotFormat="image/jpeg"
            videoConstraints={videoConstraints}
            style={styles.webcam}
          />
          {loading && <div style={styles.loaderOverlay}>⏳ Analyse en cours...</div>}
        </div>

        {/* Boutons */}
        <div style={styles.buttonGroup}>
          <button 
            onClick={handleCapture} 
            disabled={loading || autoMode}
            style={{
              ...styles.btn, 
              backgroundColor: COLORS.primary, 
              opacity: (loading || autoMode) ? 0.6 : 1,
            }}
          >
            {loading ? '⏳ Traitement...' : '🔍 Scan Manuel'}
          </button>

          <button 
            onClick={() => setAutoMode(!autoMode)} 
            style={{
              ...styles.btn, 
              backgroundColor: autoMode ? COLORS.danger : COLORS.success,
            }}
          >
            {autoMode ? '⏹ STOP AUTO' : '🔄 AUTO SCAN'}
          </button>
        </div>

        {/* Résultats */}
        <div style={styles.resultArea}>
          {result && (
            <div style={styles.successBox}>
              <div style={styles.successBoxName}>
                ✅ {String(result.name)}
              </div>
              <div style={styles.successBoxRow}>
                <span>ID Étudiant :</span>
                <span style={{ fontWeight: 'bold' }}>{String(result.studentId)}</span>
              </div>
              <div style={styles.successBoxRow}>
                <span>ID Présence :</span>
                <span style={{ fontWeight: 'bold' }}>{String(result.attendanceId)}</span>
              </div>
              <div style={styles.successBoxRow}>
                <span>Confiance :</span>
                <span style={{
                  fontWeight: 'bold',
                  color: parseFloat(result.confidence) > 80 ? COLORS.success : COLORS.warning
                }}>
                  {String(result.confidence)}%
                </span>
              </div>
              <div style={styles.successBoxMeta}>
                🕐 {String(result.timestamp)}
              </div>
            </div>
          )}

          {error && (
            <div style={styles.errorBox}>
              <strong>❌ Erreur :</strong> {String(error)}
            </div>
          )}

          {!result && !error && !loading && (
            <p style={{ textAlign: 'center', color: COLORS.textMuted, marginTop: '20px' }}>
              Capturez une image pour commencer la reconnaissance
            </p>
          )}
        </div>
      </div>
    </div>
  );
};

export default CameraRecognition;
